#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(10);}}while(0)
constexpr int N_STUDY=17,NL_STUDY=4913,POP_STUDY=93347,STEPS_STUDY=20;
template<class V>V*guarded(int n,V guard){V*base;CHECK(cudaMalloc(&base,(n+16)*sizeof(V)));std::vector<V>v(n+16,guard);CHECK(cudaMemcpy(base,v.data(),v.size()*sizeof(V),cudaMemcpyHostToDevice));return base+8;}
std::vector<double>read64(double*p,int n){std::vector<double>v(n);CHECK(cudaMemcpy(v.data(),p,n*8,cudaMemcpyDeviceToHost));return v;}
template<class V>std::vector<double>read_cast(V*p,int n){std::vector<V>v(n);CHECK(cudaMemcpy(v.data(),p,n*sizeof(V),cudaMemcpyDeviceToHost));return std::vector<double>(v.begin(),v.end());}
int main(){std::vector<double>prefix(108090),gold(221197);FILE*f=fopen("/home/imo/HeCBench_julia/src/d3q19-bgk-julia/fixture.bin","rb");if(!f||fread(prefix.data(),8,prefix.size(),f)!=prefix.size())return 4;fclose(f);f=fopen("/home/imo/HeCBench_julia/src/d3q19-bgk-julia/oracle.bin","rb");if(!f||fread(gold.data(),8,gold.size(),f)!=gold.size())return 5;fclose(f);BoxCU box;box.nx=box.ny=box.nz=N_STUDY;lbm_vars dv{};dv.f0=guarded<double>(POP_STUDY,-12345.);dv.f1=guarded<double>(POP_STUDY,-12345.);double*orig0=dv.f0,*orig1=dv.f1;dv.r=guarded<double>(NL_STUDY,-12345.);dv.u_star.u0=guarded<float>(3*NL_STUDY,-12345.f);dv.u_star.u1=dv.u_star.u0+NL_STUDY;dv.u_star.u2=dv.u_star.u0+2*NL_STUDY;dv.boundary_flag=guarded<char>(NL_STUDY,char(-83));dv.boundary_dirs=guarded<char>(NL_STUDY,char(-83));dv.boundary_values=guarded<int>(NL_STUDY,-991827);
CHECK(cudaMemcpyToSymbol(C_dirs,dirs,57));CHECK(cudaMemcpyToSymbol(C_p,outer_bounds_priority,12));CHECK(cudaMemset(dv.boundary_flag,0,NL_STUDY));CHECK(cudaMemset(dv.boundary_dirs,0,NL_STUDY));CHECK(cudaMemset(dv.boundary_values,0,4*NL_STUDY));outer_wall walls{type_b::bounce,type_b::bounce,type_b::bounce,type_b::bounce,type_b::moving_wall,type_b::bounce};make_flag<<<dim3(1,N_STUDY,N_STUDY),N_STUDY>>>(dv.boundary_flag,dv.boundary_values,dv.boundary_dirs,box,walls,N_STUDY,N_STUDY,N_STUDY,0);find_wall<D3Q19><<<dim3(1,N_STUDY,N_STUDY),N_STUDY>>>(dv.boundary_flag,dv.boundary_dirs,dv.boundary_values,box,0);CHECK(cudaDeviceSynchronize());double omega=prefix.back(),lid=prefix[prefix.size()-2];
auto reset=[&](){dv.f0=orig0;dv.f1=orig1;init_velocity_g<D3Q19><<<dim3(1,N_STUDY,N_STUDY),N_STUDY>>>(dv,box,box,N_STUDY,0,0,0,1.);CHECK(cudaDeviceSynchronize());};
auto run=[&](){for(int step=0;step<STEPS_STUDY;step++){collide_and_stream_g<D3Q19><<<dim3(1,N_STUDY,N_STUDY),64>>>(dv,box,lid,omega,true,step);double*temp=dv.f0;dv.f0=dv.f1;dv.f1=temp;CHECK(cudaDeviceSynchronize());}};
reset();run();for(int trial=1;trial<=5;trial++){reset();bool ok=true;double err=0,rel=0;std::vector<double>initial=read64(dv.f0,POP_STUDY);auto append=[](std::vector<double>&a,const std::vector<double>&b){a.insert(a.end(),b.begin(),b.end());};append(initial,read_cast(dv.boundary_flag,NL_STUDY));append(initial,read_cast(dv.boundary_dirs,NL_STUDY));append(initial,read_cast(dv.boundary_values,NL_STUDY));initial.insert(initial.end(),prefix.end()-4,prefix.end());ok&=initial.size()==prefix.size()&&memcmp(initial.data(),prefix.data(),prefix.size()*8)==0;auto t=std::chrono::steady_clock::now();run();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();std::vector<double>got=read64(dv.f0-8,POP_STUDY+16);append(got,read64(dv.f1-8,POP_STUDY+16));append(got,read_cast(dv.u_star.u0-8,3*NL_STUDY+16));append(got,read64(dv.r-8,NL_STUDY+16));append(got,read_cast(dv.boundary_flag-8,NL_STUDY+16));append(got,read_cast(dv.boundary_dirs-8,NL_STUDY+16));append(got,read_cast(dv.boundary_values-8,NL_STUDY+16));if(got.size()!=gold.size())return 6;for(size_t i=0;i<got.size();i++){double e=fabs(got[i]-gold[i]);err=std::max(err,e);rel=std::max(rel,e/(fabs(gold[i])+1.e-300));ok&=std::isfinite(got[i])&&e<=1.e-7+1.e-6*fabs(gold[i]);}size_t off=0;int counts[]={POP_STUDY,POP_STUDY,3*NL_STUDY,NL_STUDY,NL_STUDY,NL_STUDY,NL_STUDY};for(int group=0;group<7;group++){int count=counts[group];for(int k=0;k<8;k++)ok&=got[off+k]==gold[off+k]&&got[off+8+count+k]==gold[off+8+count+k];if(group>=3)for(int k=0;k<count+16;k++)ok&=got[off+k]==gold[off+k];off+=count+16;}for(int i=0;i<POP_STUDY;i++)ok&=got[8+i]>0;std::vector<char>flags(NL_STUDY);CHECK(cudaMemcpy(flags.data(),dv.boundary_flag,NL_STUDY,cudaMemcpyDeviceToHost));double mass=0;int active=0;for(int i=0;i<NL_STUDY;i++)if(flags[i]<4){active++;for(int q=0;q<19;q++)mass+=got[8+q*NL_STUDY+i];}ok&=fabs(mass-active)/active<1.e-6;std::vector<double>art=initial;append(art,got);std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*out=fopen(path.c_str(),"wb");fwrite(art.data(),8,art.size(),out);fclose(out);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":221197,\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"active_mass\":%.17g,\"active_mass_relative_drift\":%.17g,\"timing_region\":\"20_cavity_D3Q19_stream_BGK_steps_swap_sync_eachstep\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":329287,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",err,rel,mass,fabs(mass-active)/active,path.c_str());}
CHECK(cudaFree(orig0-8));CHECK(cudaFree(orig1-8));CHECK(cudaFree(dv.r-8));CHECK(cudaFree(dv.u_star.u0-8));CHECK(cudaFree(dv.boundary_flag-8));CHECK(cudaFree(dv.boundary_dirs-8));CHECK(cudaFree(dv.boundary_values-8));}
